import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { resolve } from "node:path";

const site = "https://latamworldnews.com";
const additions = [
  "Content-Signal: search=yes, ai-input=yes, ai-train=no",
  "Disallow: /editorial"
];

// Baseline: robots.txt generated by the verified Production/main base commit.
const baseline = [
  "User-Agent: *",
  "Allow: /",
  "Disallow: /api/",
  "Disallow: /buscar?*",
  "",
  `Host: ${site}/`,
  `Sitemap: ${site}/sitemap.xml`,
  `Sitemap: ${site}/sitemap-news.xml`,
  ""
].join("\n");

async function main() {
  process.env.NEXT_PUBLIC_SITE_URL = site;
  const { GET, dynamic } = await import("../app/robots.txt/route");
  assert.equal(dynamic, "force-static");
  assert.equal(existsSync(resolve("app/robots.ts")), false);
  assert.equal(existsSync(resolve("public/robots.txt")), false);

  const response = process.env.ROBOTS_TEST_URL
    ? await fetch(process.env.ROBOTS_TEST_URL, { redirect: "manual" })
    : GET();
  assert.equal(response.status, 200);
  assert.match(response.headers.get("content-type") ?? "", /^text\/plain(?:;|$)/i);
  assert.equal(response.headers.get("cache-control"), "public, max-age=14400, must-revalidate");
  const body = await response.text();
  const lines = body.split("\n");
  for (const addition of additions) {
    assert.equal(lines.filter((line) => line === addition).length, 1, addition);
  }
  assert.equal(lines.filter((line) => !additions.includes(line)).join("\n"), baseline);
  assert.deepEqual(lines.filter((line) => /^User-Agent:/i.test(line)), ["User-Agent: *"]);
  assert.equal(lines[1], additions[0], "signal belongs to the wildcard group");

  // ASCII fixtures for RFC 9309 prefix, wildcard, end anchor and longest match.
  // This checks the policy's boundaries; it does not run vendors' crawler code.
  const rules = lines.flatMap((line) => {
    const match = /^(Allow|Disallow): (.+)$/.exec(line);
    if (!match) return [];
    const [, directive, pattern] = match;
    const anchored = pattern.endsWith("$");
    const path = anchored ? pattern.slice(0, -1) : pattern;
    const expression = path.split("*").map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join(".*");
    return [{ allow: directive === "Allow", length: path.length, regex: new RegExp(`^${expression}${anchored ? "$" : ""}`) }];
  });

  const fixtures: Array<[string, boolean]> = [
    ["/editorial", false],
    ["/editorial/", false],
    ["/editorial/inbox", false],
    ["/editorial/?error=1", false],
    ["/impacto/editorial/brasil-segunda-vuelta-2026-impacto-sudamerica", true],
    ["/impacto/editorial/ejemplo?ref=home", true],
    ["/editoriales", false], // Prefix exclusion is intentional.
    ["/editorial-publico", false],
    ["/editorial?query", false],
    ["/editorial?error=1", false],
    ["/", true],
    ["/nota/ejemplo", true],
    ["/_next/static/example.js", true],
    ["/api/example", false],
    ["/buscar?q=ejemplo", false],
    ["/buscar", true],
    ["/sitemap.xml", true],
    ["/sitemap-news.xml", true]
  ];
  for (const [path, expected] of fixtures) {
    const matches = rules.filter((rule) => rule.regex.test(path))
      .sort((a, b) => b.length - a.length || Number(b.allow) - Number(a.allow));
    assert.equal(matches[0]?.allow ?? true, expected, path);
  }
  console.log(`robots route checks passed (${process.env.ROBOTS_TEST_URL ? "HTTP" : "direct GET"}; ${fixtures.length} path fixtures; only 2 authorized additions).`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
